package com.sunrise.dentalclinic.controller;
import com.sunrise.dentalclinic.dto.PatientRequest;import com.sunrise.dentalclinic.service.PatientService;import jakarta.validation.Valid;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller @RequestMapping("/patients") public class PatientController{private final PatientService service;public PatientController(PatientService s){service=s;}@GetMapping String list(@RequestParam(required=false)String q,Model m){m.addAttribute("patients",service.search(q));m.addAttribute("q",q);return "patients/list";}@GetMapping("/new")String create(Model m){m.addAttribute("patientRequest",new PatientRequest("","",""));return "patients/form";}@PostMapping String save(@Valid @ModelAttribute PatientRequest patientRequest,BindingResult errors,RedirectAttributes ra){if(errors.hasErrors())return "patients/form";var p=service.create(patientRequest);ra.addFlashAttribute("success","Patient registered successfully");return "redirect:/patients/"+p.getId();}@GetMapping("/{id}")String view(@PathVariable Long id,Model m){m.addAttribute("patient",service.get(id));return "patients/view";}@GetMapping("/{id}/edit")String edit(@PathVariable Long id,Model m){var p=service.get(id);m.addAttribute("patientRequest",new PatientRequest(p.getName(),p.getAddress(),p.getContactNumber()));m.addAttribute("patient",p);return "patients/form";}@PostMapping("/{id}")String update(@PathVariable Long id,@Valid @ModelAttribute PatientRequest patientRequest,BindingResult errors,Model m,RedirectAttributes ra){if(errors.hasErrors()){m.addAttribute("patient",service.get(id));return "patients/form";}service.update(id,patientRequest);ra.addFlashAttribute("success","Patient updated successfully");return "redirect:/patients/"+id;}}
